// matrix:table:end

function scenarios(): { scenario: Scenario; tag: string[] }[] {
  if (process.env.MATRIX_COMBO) {
    return process.env.MATRIX_COMBO.split(";").map((text) => {
      const scenario = parseCombination(text);
      return { scenario, tag: tagsFor(scenario.combination) };
    });
  }
  const only = process.env.MATRIX_ONLY?.split(",").map((s) => s.trim()).filter(Boolean);
  const unknown = only?.filter((id) => !TABLE.some((row) => row.id === id)) ?? [];
  if (unknown.length) throw new Error(`not in the matrix: ${unknown.join(", ")}; pass its values with --combo instead`);
  return TABLE.filter((row) => !only?.length || only.includes(row.id)).map((row) => ({ scenario: parseCombination(row.values), tag: [...row.tag] }));
}

for (const { scenario, tag } of scenarios()) {
  const { id, combination } = scenario;
  test(`${id} · ${DIMENSIONS.map((d) => combination[d.id]).join(" · ")}`, {
    tag,
    annotation: [
      { type: "matrix-id", description: id },
      { type: "matrix-combination", description: JSON.stringify(combination) },
    ],
  }, async ({ peer, extensionPeer, relay }, info) => {
    const withDesktop = combination.client.startsWith("desktop");
    const missing = unmet(withDesktop ? ["desktop"] : []);
    test.skip(missing.length > 0, `needs ${missing.join("; ")}`);

    const [hostKind, guestKind] = combination.client.split("-") as [Actor["kind"] | "desktop", Actor["kind"] | "desktop"];
    const open = async (kind: Actor["kind"], name: string, options: { phone?: boolean } = {}): Promise<Actor> => {
      const phone = options.phone ?? false;
      // LND's certificate is self-signed: the browsers trust it the way one trusts a node set up with a real one.
      const ignoreHTTPSErrors = combination.rail === "ln-lnd";
      // Test networks only: nothing on a Mainnet server is reached (a new profile makes no wallet by itself; New would ask).
      const offlineMainnet = combination.wallet === "testnet";
      const opened = kind === "web" ? await peer(name, { mobile: phone, ignoreHTTPSErrors, offlineMainnet }) : await extensionPeer(name, { ignoreHTTPSErrors });
      if (kind === "extension" && phone) await opened.page.setViewportSize({ width: 390, height: 844 });
      return { ...opened, kind, locale: "en", phone };
    };
    if (withDesktop) {
      // Desktop is driven through WebDriver, and does chat only: its own people, its own blocks (desktop.ts).
      // Its texts go over the DHT on Linux (no WebRTC there), a minute or two each way with the receipts.
      info.setTimeout(20 * 60_000);
      const desktopWorld = { combo: combination, info, cleanup: [] } as unknown as DesktopWorld;
      try {
        await test.step(PLAN[0].title, async () => {
          const network = await desktopNetwork(relay);
          desktopWorld.cleanup.push(network.close);
          desktopWorld.a = await openDesktopPerson(desktopWorld, "alice", network.env);
          desktopWorld.b = guestKind === "desktop" ? await openDesktopPerson(desktopWorld, "bob", network.env) : webPerson(await open("web", "bob"));
        });
        for (const step of PLAN.slice(1)) if (step.applies(combination)) await runStep(step, desktopWorld, DESKTOP_BLOCKS);
      } catch (error) {
        // WebDriver leaves no screenshot in the report: what each app showed, as text.
        for (const p of [desktopWorld.a, desktopWorld.b].filter(Boolean)) {
          const text = await p.snapshot().catch((e) => `(no snapshot: ${e})`);
          await info.attach(`${p.name} (${p.kind}) at the failure`, { body: text, contentType: "text/plain" });
        }
        throw error;
      } finally {
        for (const done of desktopWorld.cleanup.reverse()) await Promise.resolve(done()).catch(() => {});
      }
      return;
    }
    const world = { combo: combination, relay, info, open, cleanup: [] } as unknown as World;
    await test.step(PLAN[0].title, async () => {
      [world.a, world.b] = await Promise.all([open(hostKind as Actor["kind"], "alice"), open(guestKind as Actor["kind"], "bob", { phone: combination.viewport === "phone" })]);
      if (combination.locale !== "en") await setLanguage(world.b, combination.locale);
      await Promise.all([nickname(world.a, "Alice"), nickname(world.b, "Bob")]);
    });
    try {
      for (const step of PLAN.slice(1)) if (step.applies(combination)) await runStep(step, world, BROWSER_BLOCKS);
    } finally {
      for (const done of world.cleanup.reverse()) await Promise.resolve(done()).catch(() => {});
    }
    expect(world.b.page.isClosed()).toBe(false);
  });
}
